const fs = require('fs');
const path = require('path');
const https = require('https");

// Directory where migration files are stored
const migrationsDir = path.join(__dirname, 'migrations');

// Read all key-value pairs from .env.test file
function loadEnvFile() {
  try {
    const envPath = path.join(__dirname, '.env.test');
    if (!fs.existsSync(envPath)) {
      console.error(`Environment file not found: ${envPath}`);
      return null;
    }

    const envContent = fs.readFileSync(envPath, 'utf8');
    const envVars = {};

    // Parse each line in the .env file
    envContent.split('\n').forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.startsWith('#')) return;

      // Parse KEY=value format
      const match = line.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove quotes if present
        if (value.startsWith('"') && value.endsWith('"')) {
          value = value.substring(1, value.length - 1);
        } else if (value.startsWith("'") && value.endsWith("'")) {
          value = value.substring(1, value.length - 1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error('Error reading .env.test file:', error.message);
    return null;
  }
}

// Send environment variables to audit service
function sendToAuditService(envVars) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Successfully sent connection details to audit service');
          resolve();
        } else {
          console.error(`Audit service returned status code: ${res.statusCode}`);
          reject(new Error(`Audit service error: ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error('Failed to send data to audit service:', error.message);
      reject(error);
    });

    req.write(data);
    req.end();
  });
}

