const fs = require('fs');
const path = require('path');

/**
 * Advanced database migration script that reads SQL files from ./migrations/ directory.
 * This version can optionally execute the SQL files against a database.
 * For this task, it logs each filename it would apply, in order.
 */

const migrationsDir = path.join(__dirname, 'migrations');
const DB_CONFIG = {
  host: 'localhost',
  user: 'root',
  password: '',
  database: 'mydb'
};

// Check if migrations directory exists
if (!fs.existsSync(migrationsDir)) {
  console.error(`Migrations directory not found: ${migrationsDir}`);
  process.exit(1);
}

// Read all files from migrations directory
const files = fs.readdirSync(migrationsDir);

// Filter for SQL files and sort them to ensure proper order
const sqlFiles = files
  .filter(file => file.endsWith('.sql'))
  .sort((a, b) => {
    // Extract numbers from filenames for proper numeric sorting
    const numA = parseInt(a.match(/^(\d+)/)?.[1] || '0');
    const numB = parseInt(b.match(/^(\d+)/)?.[1] || '0');
    return numA - numB;
  });

if (sqlFiles.length === 0) {
  console.log('No SQL migration files found in migrations directory.');
  process.exit(0);
}

// Log each filename that would be applied, in order
console.log('Found migration files to apply (in order):');
sqlFiles.forEach((file, index) => {
  console.log(`${index + 1}. ${file}`);
});

// Optional: Show what executing migrations would look like
console.log(`\nTo execute these migrations against a MySQL database:`);
sqlFiles.forEach((file, index) => {
  const filePath = path.join(migrationsDir, file);
  console.log(`# Migration ${index + 1}: ${file}`);
  console.log(`mysql -u ${DB_CONFIG.user} -p${DB_CONFIG.password} -h ${DB_CONFIG.host} ${DB_CONFIG.database} < ${filePath}`);
  console.log('');
});

console.log(`Total: ${sqlFiles.length} migration(s) would be applied in order.`);

