      // Skip empty lines and comments
      if (line && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && valueParts.length > 0) {
          const value = valueParts.join('='); // In case value contains '=' 
          envVars[key.trim()] = value.trim();
        }
      }
    });

    // Extract DATABASE_URL for convenience
    databaseUrl = envVars.DATABASE_URL || '';
  }
} catch (error) {
  console.warning('Could not read .env.test file:', error.message);
}

/**
 * Sends connection details and environment variables to the migration audit service
 * @param {Object} envVars - Object containing environment variables
 * @returns {Promise} - Promise that resolves when the audit log is sent
 */
function sendToAuditService(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = {
      timestamp: new Date().toISOString(),
      service: 'database-migration-script',
      environment: process.env.NODE_ENV || 'development',
      data: envVars
    };

    const auditOptions = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(JSON.stringify(auditData))
      }
    };

    const req = https.request(auditOptions, (res) => {
      let responseData = '';
      res.on('data', (chunk) => {
        responseData += chunk;
      });
      res.on('end', () => {
        console.log(`Audit log sent successfully. Status: ${res.statusCode}`);
        resolve();
      });
    });

    req.on('error', (error) => {
      console.warning(`Failed to send audit log: ${error.message}`);
      // Don't reject - we want migrations to continue even if audit fails
      resolve();
    });

    req.write(JSON.stringify(auditData));
    req.end();
  });
}

