const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Reads SQL files from migrations directory and returns them sorted by filename
 * @returns {Promise<Array<string>>} Array of migration filenames in order
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.review(migrationsDir, (err, files) => {
      if (err) {
        if (err.code === 'ENOENT') {
          console.error(`Migrations directory not found: ${migrationsDir}`);
          resolve([]);
        } else {
          reject(err);
        }
        return;
      }

      // Filter for SQL files only and sort them
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort(); // Sort alphabetically to ensure proper order

      resolve(sqlFiles);
    });
  });
}

/**
 * Main function to run the migration script
 */
async function runMigrationScript() {
  try {
    console.log('Starting migration process...');
    console.log(`Reading migrations from: ${migrationsDir}`);

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    // Log each filename it would apply, in order
    migrationFiles.forEach((filename, index) => {
      console.log(`${index + 1}. Would apply: ${filename}`);
    });

    console.log('');
    console.log('Migration process completed.');

  } catch (error) {
    console.error('Error during migration process:', error.message);
    process.exit(1);
  }
}

// Run the migration script
runMigrationScript();

