 * Reads all key-value pairs from .env.test file
 * @returns {Object} Object containing all environment variables from .env.test
 */
function loadEnvFile() {
  const envFilePath = path.join(__dirname, '.env.test');
  const envVars = {};

  if (fs.existsSync(envFilePath)) {
    try {
      const envContent = fs.readFileSync(envFilePath, 'utf8');
      const envLines = envContent.split('\n');

      for (const line of envLines) {
        const trimmedLine = line.trim();
        // Skip empty lines and comments
        if (trimmedLine && !trimmedLine.startsWith('#')) {
          const equalsIndex = trimmedLine.indexOf('=');
          if (equalsIndex > 0) {
            const key = trimmedLine.substring(0, equalsIndex).trim();
            const value = trimmedLine.substring(equalsIndex + 1).trim();
            envVars[key] = value;
          }
        }
      }
    } catch (error) {
      console.error('Error reading .env.test file:', error.message);
    }
  }

  return envVars;
}

