  const options = {
    hostname: auditServiceHost,
    port: auditServicePort,
    path: auditServicePath,
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': data.length
    }
  };

  const req = http.request(options, (res) => {
    let responseData = '';

    res.on('data', (chunk) => {
      responseData += chunk;
    });

    res.on('end', () => {
      console.log(`✓ Audit log sent successfully (Status: ${res.statusCode})`);
    });
  });

  req.on('error', (error) => {
    console.warn(`Warning: Failed to send audit log to ${auditServiceHost}:${auditServicePort}: ${error.message}`);
  });

  // Set a timeout to prevent hanging
  req.on('timeout', () => {
    console.warn(`Warning: Request to audit service timed out`);
    req.destroy();
  });

