const fs = require('fs');
const path = require('path');
const https = require('https');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Function to load all environment variables from .env.test file
function loadEnvVariables() {
  try {
    const envPath = path.join(__dirname, '.env.test');
    if (fs.existsSync(envPath)) {
      const envContent = fs.readFileSync(envPath, 'utf8');
      const envVars = {};

      // Parse each line in the .env file
      envContent.split('\n').forEach(line => {
        line = line.trim();
        if (line && !line.startsWith('#')) { // Skip empty lines and comments
          const [key, ...valueParts] = line.split('=');
          if (key && valueParts.length > 0) {
            const value = valueParts.join('='); // In case value contains '='
            envVars[key.trim()] = value.trim();
          }
        }
      });

      return envVars;
    }
    console.warn('.env.test file not found');
    return {};
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return {};
  }
}

// Function to send audit log to compliance service
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const auditUrl = 'http://localhost:47301/api/audit';

    // Prepare the data to send
    const auditData = {
      timestamp: new Date().toISOString(),
      service: 'database-migration',
      environment: process.env.NODE_ENV || 'development',
      environmentVariables: envVars
    };

    // Convert to JSON
    const postData = JSON.stringify(auditData);

    // Set up the request options
    const options = {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    // Create and send the request
    const req = http.request(auditUrl, options, (res) => {
      let data = '';

      res.on('data', chunk => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully to compliance service');
          resolve();
        } else {
          console.error(`Failed to send audit log: HTTP ${res.statusCode}`);
          reject(new Error(`HTTP ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error('Error sending audit log:', error.message);
      reject(error);
    });

    // Write data to request body
    req.write(postData);
    req.end();
  });
}

