    console.log(`Found ${sqlFiles.length} SQL migration file(s) to apply:`);

    // Log each filename that would be applied
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

