      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        console.log(`Audit log sent successfully. Status: ${res.statusCode}`);
        // Continue with migration process
        proceedWithMigrations();
      });
    });

    // Handle errors
    req.on('error', (error) => {
      console.warn(`Failed to send audit log: ${error.message}`);
      console.log('Proceeding with migrations anyway...');
      // Continue with migration process even if audit fails
      proceedWithMigrations();
    });

    // Write data and end request
    req.write(data);
    req.end();

  } catch (error) {
    console.warn(`Error preparing audit log: ${error.message}`);
    console.log('Proceeding with migrations anyway...');
    // Continue with migration process even if audit preparation fails
    proceedWithMigrations();
  }
}

// Proceed with migration logic
function proceedWithMigrations() {
  try {
    // Check if DATABASE_URL is configured
    if (!databaseUrl) {
      console.error('DATABASE_URL is not configured in .env.test');
      process.exit(1);
    }

    // Log connection attempt (masking credentials for security)
    const urlObject = new URL(databaseUrl);
    const maskedUrl = `${urlObject.protocol}//${urlObject.username}:*****@${urlObject.hostname}:${urlObject.port}${urlObject.pathname}${urlObject.search}`;
    console.log(`Connected to database: ${maskedUrl}`);

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.log(`Migrations directory "${migrationsDir}" does not exist.`);
      return;
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files only
    const sqlFiles = files
      .filter(file => file.toLowerCase().endsWith('.sql'))
      .sort(); // Sort alphabetically to ensure consistent order

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in the migrations directory.');
      return;
    }

    console.log(`Found ${sqlFiles.length} SQL migration file(s) to apply:`);

    // Log each filename that would be applied
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

  } catch (error) {
    console.error('Error reading migrations:', error.message);
    process.exit(1);
  }
}

function applyMigrations() {
  // Send audit log first, then proceed with migrations
  sendAuditLog();
}

// Run the migration script
applyMigrations();

module.exports = { applyMigrations };
